"use client";

/**
 * ConsentProvider and useConsent.
 *
 * Categories:
 *   necessary  always on. Session, CSRF, load balancing. Disclosed, no consent needed.
 *   analytics  off until the person chooses. Notice plus a real choice.
 *   marketing  off until opt-in. Pixels and ad tags (s69, Regulator Direct
 *              Marketing Guidance Note, Dec 2024).
 *
 * Consent is versioned. When policyVersion changes, the stored choice no longer
 * applies and the banner shows again. Consent must be informed (s1), so a
 * choice made against old wording is not carried forward.
 *
 * Storage is localStorage, and every access is wrapped in try/catch. If storage
 * throws (private mode, blocked site data) the app still works: the choice
 * lives in memory for the session and nothing non-essential loads.
 *
 * Browser storage is a convenience, not evidence. Use onChange to record each
 * decision server-side (s11(2)(a): burden of proof is on the responsible party).
 */

import * as React from "react";

export type ConsentCategory = "necessary" | "analytics" | "marketing";
export type OptionalCategory = Exclude<ConsentCategory, "necessary">;

export interface ConsentState {
  necessary: true;
  analytics: boolean;
  marketing: boolean;
  /** The policy or notice version the person saw when choosing. */
  policyVersion: string;
  /** ISO timestamp of the choice. */
  decidedAt: string;
}

export type ConsentSource = "accept_all" | "reject_all" | "preferences" | "withdraw";

export interface ConsentChange {
  state: ConsentState;
  previous: ConsentState | null;
  source: ConsentSource;
  /** Categories whose value changed, with the new value. */
  changed: Array<{ category: OptionalCategory; granted: boolean }>;
}

export interface ConsentContextValue {
  /** null until the person has decided for the current policyVersion. */
  consent: ConsentState | null;
  /** True once storage has been read on the client. Avoids a banner flash on SSR. */
  ready: boolean;
  hasDecided: boolean;
  policyVersion: string;
  /** necessary is always true. Others are false until granted. */
  has: (category: ConsentCategory) => boolean;
  acceptAll: () => void;
  rejectAll: () => void;
  /** Save a specific set of choices from the preferences dialog. */
  save: (choices: Partial<Record<OptionalCategory, boolean>>) => void;
  /** Withdraw all optional consent (s11(2)(b)). As easy as giving it. */
  withdrawAll: () => void;
  preferencesOpen: boolean;
  openPreferences: () => void;
  closePreferences: () => void;
  setPreferencesOpen: (open: boolean) => void;
}

const ConsentContext = React.createContext<ConsentContextValue | null>(null);

export interface ConsentProviderProps {
  children: React.ReactNode;
  /**
   * Version of the cookie notice or privacy notice wording. Bump it whenever
   * the categories, vendors or purposes change. Use a semver or a hash.
   */
  policyVersion: string;
  /** localStorage key. Defaults to "popia_consent". */
  storageKey?: string;
  /**
   * Called after every decision. Use it to record the event server-side, for
   * example via the consent edge function or a Supabase insert. Errors thrown
   * here are caught and logged without personal information.
   */
  onChange?: (change: ConsentChange) => void | Promise<void>;
}

const OPTIONAL: OptionalCategory[] = ["analytics", "marketing"];

function safeRead(key: string): unknown {
  try {
    if (typeof window === "undefined") return null;
    const raw = window.localStorage.getItem(key);
    return raw ? (JSON.parse(raw) as unknown) : null;
  } catch {
    return null;
  }
}

function safeWrite(key: string, value: ConsentState): void {
  try {
    if (typeof window === "undefined") return;
    window.localStorage.setItem(key, JSON.stringify(value));
  } catch {
    // Storage unavailable. Choice stays in memory for this session.
  }
}

function isConsentState(v: unknown): v is ConsentState {
  if (!v || typeof v !== "object") return false;
  const o = v as Record<string, unknown>;
  return (
    o.necessary === true &&
    typeof o.analytics === "boolean" &&
    typeof o.marketing === "boolean" &&
    typeof o.policyVersion === "string" &&
    typeof o.decidedAt === "string"
  );
}

export function ConsentProvider({
  children,
  policyVersion,
  storageKey = "popia_consent",
  onChange,
}: ConsentProviderProps) {
  const [consent, setConsent] = React.useState<ConsentState | null>(null);
  const [ready, setReady] = React.useState(false);
  const [preferencesOpen, setPreferencesOpen] = React.useState(false);
  const consentRef = React.useRef<ConsentState | null>(null);
  const onChangeRef = React.useRef(onChange);
  onChangeRef.current = onChange;

  // Read on the client only, after mount.
  React.useEffect(() => {
    const stored = safeRead(storageKey);
    // A choice made under a different policy version does not count.
    const valid = isConsentState(stored) && stored.policyVersion === policyVersion ? stored : null;
    consentRef.current = valid;
    setConsent(valid);
    setReady(true);
  }, [storageKey, policyVersion]);

  // Keep tabs in sync. A withdrawal in one tab applies to all.
  React.useEffect(() => {
    if (typeof window === "undefined") return;
    const handler = (e: StorageEvent) => {
      if (e.key !== storageKey) return;
      const next = safeRead(storageKey);
      const valid = isConsentState(next) && next.policyVersion === policyVersion ? next : null;
      consentRef.current = valid;
      setConsent(valid);
    };
    try {
      window.addEventListener("storage", handler);
      return () => window.removeEventListener("storage", handler);
    } catch {
      return undefined;
    }
  }, [storageKey, policyVersion]);

  const commit = React.useCallback(
    (choices: Record<OptionalCategory, boolean>, source: ConsentSource) => {
      const previous = consentRef.current;
      const next: ConsentState = {
        necessary: true,
        analytics: choices.analytics,
        marketing: choices.marketing,
        policyVersion,
        decidedAt: new Date().toISOString(),
      };
      const changed = OPTIONAL.filter((c) => (previous ? previous[c] !== next[c] : true)).map((c) => ({
        category: c,
        granted: next[c],
      }));
      consentRef.current = next;
      setConsent(next);
      safeWrite(storageKey, next);
      setPreferencesOpen(false);
      const cb = onChangeRef.current;
      if (cb) {
        try {
          void Promise.resolve(cb({ state: next, previous, source, changed })).catch(() => {
            // Do not log the payload. It may be joined to a user id.
            console.warn("ConsentProvider: onChange failed");
          });
        } catch {
          console.warn("ConsentProvider: onChange failed");
        }
      }
    },
    [policyVersion, storageKey],
  );

  const value = React.useMemo<ConsentContextValue>(
    () => ({
      consent,
      ready,
      hasDecided: consent !== null,
      policyVersion,
      has: (category) => (category === "necessary" ? true : Boolean(consent?.[category])),
      acceptAll: () => commit({ analytics: true, marketing: true }, "accept_all"),
      rejectAll: () => commit({ analytics: false, marketing: false }, "reject_all"),
      save: (choices) =>
        commit(
          {
            analytics: choices.analytics ?? false,
            marketing: choices.marketing ?? false,
          },
          "preferences",
        ),
      withdrawAll: () => commit({ analytics: false, marketing: false }, "withdraw"),
      preferencesOpen,
      openPreferences: () => setPreferencesOpen(true),
      closePreferences: () => setPreferencesOpen(false),
      setPreferencesOpen,
    }),
    [consent, ready, policyVersion, preferencesOpen, commit],
  );

  return <ConsentContext.Provider value={value}>{children}</ConsentContext.Provider>;
}

export function useConsent(): ConsentContextValue {
  const ctx = React.useContext(ConsentContext);
  if (!ctx) {
    throw new Error("useConsent must be used inside <ConsentProvider>.");
  }
  return ctx;
}

/** Same as useConsent but returns null outside a provider. For optional integrations. */
export function useOptionalConsent(): ConsentContextValue | null {
  return React.useContext(ConsentContext);
}

"use client";

/**
 * Cookie and tracker consent banner.
 *
 * Design rules (no dark patterns):
 *   - "Accept all" and "Reject all" use the same size and the same visual weight.
 *   - "Choose" opens a dialog with one switch per optional category.
 *   - Optional switches start off. Nothing non-essential loads before a choice.
 *   - The banner does not block the page and has no countdown or nagging copy.
 *   - Links to the privacy notice and cookie notice sit in the banner (s18).
 *
 * Consent must be voluntary, specific and informed (s1). Marketing pixels need
 * opt-in (s69, Regulator Direct Marketing Guidance Note, Dec 2024).
 */

import * as React from "react";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { useConsent, type OptionalCategory } from "@/components/popia/consent-provider";

export interface ConsentCategoryCopy {
  title: string;
  description: string;
}

export interface ConsentBannerProps {
  /** Responsible party name as it appears in the privacy notice. */
  companyName: string;
  privacyNoticeUrl: string;
  cookieNoticeUrl: string;
  /** Override default copy. Keep it plain and specific. */
  copy?: {
    heading?: string;
    body?: string;
    necessary?: ConsentCategoryCopy;
    analytics?: ConsentCategoryCopy;
    marketing?: ConsentCategoryCopy;
  };
  className?: string;
}

const DEFAULT_COPY = {
  heading: "Cookies and similar tools",
  body:
    "We use necessary cookies to run this site. With your permission we also use analytics cookies to understand how the site is used, and marketing cookies to measure and show adverts. You can change your mind at any time.",
  necessary: {
    title: "Necessary",
    description: "Needed for the site to work, for example to keep you signed in and to protect forms. Always on.",
  },
  analytics: {
    title: "Analytics",
    description: "Counts visits and shows us which pages are used, so we can improve the site.",
  },
  marketing: {
    title: "Marketing",
    description: "Lets advertising partners measure our adverts and show you relevant ones on other sites.",
  },
} as const;

export function ConsentBanner({
  companyName,
  privacyNoticeUrl,
  cookieNoticeUrl,
  copy,
  className,
}: ConsentBannerProps) {
  const { ready, hasDecided, acceptAll, rejectAll, save, consent, preferencesOpen, setPreferencesOpen, openPreferences } =
    useConsent();

  const text = {
    heading: copy?.heading ?? DEFAULT_COPY.heading,
    body: copy?.body ?? DEFAULT_COPY.body,
    necessary: copy?.necessary ?? DEFAULT_COPY.necessary,
    analytics: copy?.analytics ?? DEFAULT_COPY.analytics,
    marketing: copy?.marketing ?? DEFAULT_COPY.marketing,
  };

  // Draft state for the dialog. Starts from the stored choice, or all off.
  const [draft, setDraft] = React.useState<Record<OptionalCategory, boolean>>({
    analytics: false,
    marketing: false,
  });
  React.useEffect(() => {
    if (preferencesOpen) {
      setDraft({ analytics: consent?.analytics ?? false, marketing: consent?.marketing ?? false });
    }
  }, [preferencesOpen, consent]);

  const headingId = React.useId();
  const bodyId = React.useId();

  const showBanner = ready && !hasDecided;

  return (
    <>
      {showBanner && (
        <section
          role="region"
          aria-labelledby={headingId}
          aria-describedby={bodyId}
          className={[
            "fixed inset-x-0 bottom-0 z-50 border-t bg-background p-4 shadow-lg sm:p-6",
            className ?? "",
          ].join(" ")}
        >
          <div className="mx-auto flex max-w-5xl flex-col gap-4 md:flex-row md:items-end md:justify-between">
            <div className="space-y-2 text-sm">
              <h2 id={headingId} className="text-base font-semibold">
                {text.heading}
              </h2>
              <p id={bodyId} className="text-muted-foreground">
                {text.body}
              </p>
              <p className="text-muted-foreground">
                {companyName} is responsible for this site. Read our{" "}
                <a href={privacyNoticeUrl} className="underline underline-offset-4">
                  Privacy Notice
                </a>{" "}
                and{" "}
                <a href={cookieNoticeUrl} className="underline underline-offset-4">
                  Cookie Notice
                </a>
                .
              </p>
            </div>
            {/* Equal prominence: same variant and size for accept and reject. */}
            <div className="flex flex-col gap-2 sm:flex-row sm:shrink-0">
              <Button type="button" variant="outline" onClick={openPreferences} aria-haspopup="dialog">
                Choose
              </Button>
              <Button type="button" onClick={rejectAll}>
                Reject all
              </Button>
              <Button type="button" onClick={acceptAll}>
                Accept all
              </Button>
            </div>
          </div>
        </section>
      )}

      <Dialog open={preferencesOpen} onOpenChange={setPreferencesOpen}>
        <DialogContent className="sm:max-w-lg">
          <DialogHeader>
            <DialogTitle>Cookie preferences</DialogTitle>
            <DialogDescription>
              Choose which optional cookies {companyName} may use. Optional cookies are off until you switch them on.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4">
            <CategoryRow
              id="popia-consent-necessary"
              title={text.necessary.title}
              description={text.necessary.description}
              checked
              disabled
            />
            <CategoryRow
              id="popia-consent-analytics"
              title={text.analytics.title}
              description={text.analytics.description}
              checked={draft.analytics}
              onCheckedChange={(v) => setDraft((d) => ({ ...d, analytics: v }))}
            />
            <CategoryRow
              id="popia-consent-marketing"
              title={text.marketing.title}
              description={text.marketing.description}
              checked={draft.marketing}
              onCheckedChange={(v) => setDraft((d) => ({ ...d, marketing: v }))}
            />
          </div>

          <p className="text-xs text-muted-foreground">
            More detail in our{" "}
            <a href={cookieNoticeUrl} className="underline underline-offset-4">
              Cookie Notice
            </a>
            .
          </p>

          <DialogFooter className="gap-2 sm:gap-2">
            <Button type="button" variant="outline" onClick={rejectAll}>
              Reject all
            </Button>
            <Button type="button" variant="outline" onClick={acceptAll}>
              Accept all
            </Button>
            <Button type="button" onClick={() => save(draft)}>
              Save choices
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

interface CategoryRowProps {
  id: string;
  title: string;
  description: string;
  checked: boolean;
  disabled?: boolean;
  onCheckedChange?: (checked: boolean) => void;
}

function CategoryRow({ id, title, description, checked, disabled, onCheckedChange }: CategoryRowProps) {
  const descId = `${id}-desc`;
  return (
    <div className="flex items-start justify-between gap-4 rounded-md border p-3">
      <div className="space-y-1">
        <Label htmlFor={id} className="font-medium">
          {title}
          {disabled ? <span className="ml-2 text-xs font-normal text-muted-foreground">(always on)</span> : null}
        </Label>
        <p id={descId} className="text-sm text-muted-foreground">
          {description}
        </p>
      </div>
      <Switch
        id={id}
        checked={checked}
        disabled={disabled}
        onCheckedChange={onCheckedChange}
        aria-describedby={descId}
      />
    </div>
  );
}

/**
 * A footer link that reopens preferences. Withdrawal must be as easy as
 * giving consent (s11(2)(b)), so put this on every page.
 */
export function ConsentPreferencesLink({ className, children }: { className?: string; children?: React.ReactNode }) {
  const { openPreferences } = useConsent();
  return (
    <button
      type="button"
      onClick={openPreferences}
      aria-haspopup="dialog"
      className={className ?? "text-sm underline underline-offset-4"}
    >
      {children ?? "Cookie preferences"}
    </button>
  );
}

"use client";

/**
 * ConsentGate, loadScript and Google Consent Mode v2 helpers.
 *
 * Nothing in the analytics or marketing category may load before the person
 * opts in. That covers pixels, tag managers, session replay and ad scripts
 * (s69 and the Regulator's Direct Marketing Guidance Note, Dec 2024; s18 notice).
 * Server-side tracking (Meta CAPI, server GTM) is still processing of personal
 * information and needs the same consent. Hashing is not anonymisation.
 *
 * Usage:
 *   <ConsentGate category="marketing" src="https://connect.facebook.net/en_US/fbevents.js" />
 *   <ConsentGate category="analytics" fallback={<p>Enable analytics cookies to see this.</p>}>
 *     <EmbeddedDashboard />
 *   </ConsentGate>
 *
 * Google tag:
 *   // Before any Google tag runs, as early as possible:
 *   initGoogleConsentMode();
 *   // Inside ConsentProvider:
 *   <GoogleConsentModeSync />
 */

import * as React from "react";
import { useConsent, type ConsentCategory, type ConsentState } from "@/components/popia/consent-provider";

/* ------------------------------------------------------------------ */
/* loadScript                                                          */
/* ------------------------------------------------------------------ */

export interface LoadScriptOptions {
  /** Used to de-duplicate. Defaults to the src. */
  id?: string;
  async?: boolean;
  defer?: boolean;
  /** Extra attributes, for example data-domain for Plausible. */
  attributes?: Record<string, string>;
  /** Subresource integrity hash, when the vendor publishes one. */
  integrity?: string;
  crossOrigin?: "anonymous" | "use-credentials";
  nonce?: string;
}

const loaded = new Map<string, Promise<void>>();

/**
 * Inject a script tag once. Returns a promise that resolves on load.
 * Only call this after consent for the script's category.
 */
export function loadScript(src: string, options: LoadScriptOptions = {}): Promise<void> {
  if (typeof document === "undefined") return Promise.resolve();
  const key = options.id ?? src;
  const existing = loaded.get(key);
  if (existing) return existing;

  const p = new Promise<void>((resolve, reject) => {
    try {
      const s = document.createElement("script");
      s.src = src;
      s.async = options.async ?? true;
      if (options.defer) s.defer = true;
      if (options.id) s.id = options.id;
      if (options.integrity) s.integrity = options.integrity;
      if (options.crossOrigin) s.crossOrigin = options.crossOrigin;
      if (options.nonce) s.nonce = options.nonce;
      for (const [k, v] of Object.entries(options.attributes ?? {})) s.setAttribute(k, v);
      s.onload = () => resolve();
      s.onerror = () => {
        loaded.delete(key);
        reject(new Error(`Failed to load script ${key}`));
      };
      document.head.appendChild(s);
    } catch (err) {
      loaded.delete(key);
      reject(err instanceof Error ? err : new Error("Failed to load script"));
    }
  });
  loaded.set(key, p);
  return p;
}

/* ------------------------------------------------------------------ */
/* ConsentGate                                                         */
/* ------------------------------------------------------------------ */

export interface ConsentGateProps {
  category: ConsentCategory;
  /** Rendered only after consent for this category. */
  children?: React.ReactNode;
  /** Rendered while consent is missing. Keep it neutral, no pressure copy. */
  fallback?: React.ReactNode;
  /** Optional script to load after consent. */
  src?: string;
  scriptOptions?: LoadScriptOptions;
  /** Called once after consent is present (and after the script loads, if src is set). */
  onConsented?: () => void;
}

export function ConsentGate({ category, children, fallback = null, src, scriptOptions, onConsented }: ConsentGateProps) {
  const { ready, has } = useConsent();
  const allowed = ready && has(category);
  const firedRef = React.useRef(false);
  const onConsentedRef = React.useRef(onConsented);
  onConsentedRef.current = onConsented;
  const optionsKey = JSON.stringify(scriptOptions ?? {});

  React.useEffect(() => {
    if (!allowed || firedRef.current) return;
    let cancelled = false;
    const done = () => {
      if (cancelled || firedRef.current) return;
      firedRef.current = true;
      onConsentedRef.current?.();
    };
    if (src) {
      loadScript(src, scriptOptions).then(done, () => {
        console.warn("ConsentGate: script failed to load");
      });
    } else {
      done();
    }
    return () => {
      cancelled = true;
    };
    // optionsKey stands in for scriptOptions identity.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [allowed, src, optionsKey]);

  // Note: a script that has already run cannot be unloaded. On withdrawal,
  // children unmount and the GoogleConsentModeSync update fires. For other
  // vendors call their opt-out API (for example fbq('consent', 'revoke')) in
  // the ConsentProvider onChange callback, and reload the page if needed.
  if (!allowed) return <>{fallback}</>;
  return <>{children}</>;
}

/* ------------------------------------------------------------------ */
/* Google Consent Mode v2                                              */
/* ------------------------------------------------------------------ */

type ConsentValue = "granted" | "denied";

export interface GoogleConsentSignals {
  ad_storage: ConsentValue;
  ad_user_data: ConsentValue;
  ad_personalization: ConsentValue;
  analytics_storage: ConsentValue;
  functionality_storage?: ConsentValue;
  personalization_storage?: ConsentValue;
  security_storage?: ConsentValue;
}

type Gtag = (...args: unknown[]) => void;

declare global {
  interface Window {
    dataLayer?: unknown[];
    gtag?: Gtag;
  }
}

function ensureGtag(): Gtag | null {
  if (typeof window === "undefined") return null;
  window.dataLayer = window.dataLayer ?? [];
  if (!window.gtag) {
    // Standard gtag shim. It must push the arguments object, not an array.
    window.gtag = function gtag() {
      // eslint-disable-next-line prefer-rest-params
      (window.dataLayer as unknown[]).push(arguments);
    };
  }
  return window.gtag;
}

export const DENIED_DEFAULTS: GoogleConsentSignals = {
  ad_storage: "denied",
  ad_user_data: "denied",
  ad_personalization: "denied",
  analytics_storage: "denied",
  functionality_storage: "granted", // necessary only
  personalization_storage: "denied",
  security_storage: "granted", // necessary only
};

/**
 * Set Consent Mode defaults to denied. Call this before any Google tag loads,
 * ideally in an inline script in index.html or the Next.js root layout.
 * Defaults to denied is the POPIA-safe starting point (opt-in, s69).
 */
export function initGoogleConsentMode(options: { waitForUpdateMs?: number; urlPassthrough?: boolean } = {}): void {
  const gtag = ensureGtag();
  if (!gtag) return;
  gtag("consent", "default", {
    ...DENIED_DEFAULTS,
    wait_for_update: options.waitForUpdateMs ?? 500,
  });
  // Redact ad click identifiers while ad_storage is denied.
  gtag("set", "ads_data_redaction", true);
  if (options.urlPassthrough) gtag("set", "url_passthrough", true);
}

/** Map our categories to Google's consent signals. */
export function toGoogleSignals(consent: Pick<ConsentState, "analytics" | "marketing"> | null): GoogleConsentSignals {
  const a: ConsentValue = consent?.analytics ? "granted" : "denied";
  const m: ConsentValue = consent?.marketing ? "granted" : "denied";
  return {
    ad_storage: m,
    ad_user_data: m,
    ad_personalization: m,
    analytics_storage: a,
    functionality_storage: "granted",
    personalization_storage: m,
    security_storage: "granted",
  };
}

/** Push a consent update. Call on every change, including withdrawal. */
export function updateGoogleConsent(consent: Pick<ConsentState, "analytics" | "marketing"> | null): void {
  const gtag = ensureGtag();
  if (!gtag) return;
  gtag("consent", "update", toGoogleSignals(consent));
}

/**
 * Keeps Google Consent Mode in step with ConsentProvider. Render once inside
 * the provider. Renders nothing.
 */
export function GoogleConsentModeSync() {
  const { ready, consent } = useConsent();
  const analytics = consent?.analytics ?? false;
  const marketing = consent?.marketing ?? false;
  React.useEffect(() => {
    if (!ready) return;
    updateGoogleConsent({ analytics, marketing });
  }, [ready, analytics, marketing]);
  return null;
}

/**
 * Inline snippet for index.html or a Next.js <Script strategy="beforeInteractive">.
 * Paste it above the Google tag so defaults are set first.
 */
export const GOOGLE_CONSENT_DEFAULTS_SNIPPET = `window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments);}gtag('consent','default',{ad_storage:'denied',ad_user_data:'denied',ad_personalization:'denied',analytics_storage:'denied',functionality_storage:'granted',personalization_storage:'denied',security_storage:'granted',wait_for_update:500});gtag('set','ads_data_redaction',true);`;

/**
 * Consent record types and helpers.
 *
 * Consent must be voluntary, specific and informed (s1). The burden of proof
 * is on the responsible party (s11(2)(a)), so store evidence, not a boolean:
 * who, what wording and version, when, how, and every withdrawal.
 *
 * Records map to privacy.consent_events in
 * supabase/migrations/0001_privacy_schema.sql. That table is append-only.
 * A withdrawal is a new event, never an update (s11(2)(b)).
 */

/** Purposes are free text in the database. These are the defaults this registry emits. */
export type ConsentPurpose =
  | "analytics_cookies"
  | "marketing_cookies"
  | "marketing_email"
  | "marketing_sms"
  | "marketing_whatsapp"
  | "marketing_phone"
  | (string & {});

export type ConsentAction = "granted" | "withdrawn";

export type ConsentChannel = "web_form" | "cookie_banner" | "app" | "privacy_centre" | "form4_email" | (string & {});

/** Payload shape for an insert into privacy.consent_events (snake_case to match the table). */
export interface ConsentEventPayload {
  purpose: ConsentPurpose;
  action: ConsentAction;
  /** Hash or semver of the exact wording shown. */
  notice_version: string;
  /** The literal text shown to the person. */
  wording: string;
  channel: ConsentChannel;
  source_url?: string | null;
  user_agent?: string | null;
  /** s35: parent or guardian for a child. */
  competent_person_id?: string | null;
  /** Client-side timestamp. The database also sets created_at. */
  occurred_at: string;
}

/**
 * SHA-256 hex digest of the wording, using SubtleCrypto. Works in modern
 * browsers (secure contexts), Deno and Node 18+.
 *
 * Normalises whitespace first so formatting changes do not change the hash,
 * but any change to the words does.
 */
export async function hashWording(wording: string): Promise<string> {
  const normalised = wording.replace(/\s+/g, " ").trim();
  const subtle = globalThis.crypto?.subtle;
  if (!subtle) {
    // Insecure context (plain http) or very old runtime. Fail loudly rather
    // than store an unverifiable record.
    throw new Error("SubtleCrypto is not available. Serve the page over HTTPS.");
  }
  const bytes = new TextEncoder().encode(normalised);
  const digest = await subtle.digest("SHA-256", bytes);
  return Array.from(new Uint8Array(digest))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

/** Short, human-friendly version label from a hash: "sha256:1a2b3c4d5e6f". */
export function versionFromHash(hash: string): string {
  return `sha256:${hash.slice(0, 12)}`;
}

export interface BuildConsentEventInput {
  purpose: ConsentPurpose;
  action: ConsentAction;
  wording: string;
  channel: ConsentChannel;
  /** If omitted, the version is derived from the wording hash. */
  noticeVersion?: string;
  competentPersonId?: string | null;
  /** Defaults to window.location.href without query string or hash, when available. */
  sourceUrl?: string | null;
  /** Defaults to navigator.userAgent when available. Set null to skip. */
  userAgent?: string | null;
}

function defaultSourceUrl(): string | null {
  try {
    if (typeof window === "undefined") return null;
    // Drop query and fragment: they often carry email addresses or tokens.
    return `${window.location.origin}${window.location.pathname}`;
  } catch {
    return null;
  }
}

function defaultUserAgent(): string | null {
  try {
    return typeof navigator === "undefined" ? null : navigator.userAgent;
  } catch {
    return null;
  }
}

/**
 * Build a consent event payload ready to insert. The subject is not included:
 * the server derives it from the authenticated session (never trust a
 * user id sent from the browser). IP is hashed server-side, see
 * supabase/functions/consent.
 */
export async function buildConsentEvent(input: BuildConsentEventInput): Promise<ConsentEventPayload> {
  const hash = await hashWording(input.wording);
  return {
    purpose: input.purpose,
    action: input.action,
    notice_version: input.noticeVersion ?? versionFromHash(hash),
    wording: input.wording,
    channel: input.channel,
    source_url: input.sourceUrl === undefined ? defaultSourceUrl() : input.sourceUrl,
    user_agent: input.userAgent === undefined ? defaultUserAgent() : input.userAgent,
    competent_person_id: input.competentPersonId ?? null,
    occurred_at: new Date().toISOString(),
  };
}

/** Build several events at once, for example one per marketing channel. */
export async function buildConsentEvents(inputs: BuildConsentEventInput[]): Promise<ConsentEventPayload[]> {
  return Promise.all(inputs.map(buildConsentEvent));
}
